const CAP = 1000;
const DEFAULT_NOTIONAL = 500;
const req = $('Normalize Thesis Request').first().json;
const out = $input.first().json.output || {};
const re = /^[A-Z]{1,5}(\.[A-Z])?$/;
const errors = [];
const asset = String(out.asset || '').toUpperCase().trim();
const benchmark = String(out.benchmark || '').toUpperCase().trim();
let status = out.status || 'needs_clarification';
if (!req.thesis) { status = 'needs_clarification'; errors.push('No thesis supplied'); }
if (status === 'proposal') {
  if (!re.test(asset)) errors.push('Invalid or missing asset symbol');
  if (!re.test(benchmark)) errors.push('Invalid or missing benchmark symbol');
  if (String(out.direction || '').toLowerCase() !== 'long') errors.push('V1 is long-only');
  const h = Number(out.horizon_days);
  if (!(h >= 1 && h <= 252)) errors.push('Horizon must be 1-252 trading days');
  for (const k of ['falsifiable_claim', 'entry_rule', 'exit_rule', 'invalidation_rule']) {
    if (!out[k]) errors.push('Missing ' + k);
  }
  if (errors.length) status = 'validation_failed';
}
let notional = Number(req.notional_usd) || Number(out.suggested_notional_usd) || DEFAULT_NOTIONAL;
const allocationCapped = notional > CAP;
notional = Math.min(Math.max(notional, 1), CAP);
const stamp = new Date().toISOString().slice(0, 10).replace(/-/g, '');
const experimentId = 'TL-' + stamp + '-' + Math.random().toString(36).slice(2, 8).toUpperCase();
return [{ json: {
  experiment_id: experimentId,
  status,
  record_status: status === 'proposal' ? 'proposed' : status,
  validation_errors: errors,
  thesis: req.thesis,
  asset,
  benchmark,
  direction: 'long',
  horizon_days: Number(out.horizon_days) || 0,
  falsifiable_claim: out.falsifiable_claim || '',
  notional_usd: notional,
  allocation_capped: allocationCapped,
  proposal: out,
  proposed_at: new Date().toISOString(),
  requires_approval: status === 'proposal',
} }];

const CAP = 1000;
const PAPER_BASE = 'https://paper-api.alpaca.markets';
const body = $('ThesisLab Webhook').first().json.body || {};
const row = $input.first().json || {};
const reasons = [];
if (!row.experiment_id) {
  reasons.push('Experiment not found');
} else {
  if (row.status !== 'proposed') reasons.push('Experiment status is "' + row.status + '"; only proposed experiments can be approved. Submit a new proposal instead.');
  if (!/^[A-Z]{1,5}(\.[A-Z])?$/.test(row.asset || '')) reasons.push('Invalid symbol');
  if (row.direction !== 'long') reasons.push('V1 is long-only');
  if (!(Number(row.notional_usd) > 0 && Number(row.notional_usd) <= CAP)) reasons.push('Allocation outside the $' + CAP + ' cap');
}
const confirmed = body.confirm === true || body.confirm === 'true';
if (!confirmed) reasons.push('Explicit human confirmation (confirm: true) is required');
if (!PAPER_BASE.startsWith('https://paper-api.alpaca.markets')) reasons.push('Paper endpoint verification failed');
return [{ json: {
  ok: reasons.length === 0,
  reasons,
  experiment_id: row.experiment_id || body.experiment_id || null,
  asset: row.asset || null,
  benchmark: row.benchmark || null,
  thesis: row.thesis || '',
  falsifiable_claim: row.falsifiable_claim || '',
  horizon_days: row.horizon_days || 0,
  notional_usd: Number(row.notional_usd) || 0,
} }];

const BAND = 0.01; // +/-1% edge band: Held up / Didn't hold up, otherwise Too close to call
const row = $('Load Experiment for Eval').first().json;
const order = $('Get Order Fill').first().json;
const bars = ($input.first().json || {}).bars || {};
const a = bars[row.asset] || [];
const b = bars[row.benchmark] || [];
const fill = Number(order.filled_avg_price);
if (!fill || !a.length || !b.length) {
  return [{ json: { ok: false, experiment_id: row.experiment_id, error: 'Missing fill price or benchmark data; no result computed.', order_status: order.status || null } }];
}
const assetLast = Number(a[a.length - 1].c);
const benchFirst = Number(b[0].o);
const benchLast = Number(b[b.length - 1].c);
const assetReturn = assetLast / fill - 1;
const benchmarkReturn = benchLast / benchFirst - 1;
const alpha = assetReturn - benchmarkReturn;
const tradingDays = a.length;
const complete = tradingDays >= Number(row.horizon_days || 0);
let verdict = 'inconclusive';
if (alpha > BAND) verdict = 'supported';
else if (alpha < -BAND) verdict = 'rejected';
const pct = (x) => (x * 100).toFixed(2) + '%';
const LABELS = { supported: 'Held up', rejected: "Didn't hold up", inconclusive: 'Too close to call' };
const outcome = {
  verdict: complete ? verdict : 'interim_' + verdict,
  verdict_label: (complete ? '' : 'Early read: ') + LABELS[verdict],
  horizon_complete: complete,
  trading_days_elapsed: tradingDays,
  horizon_days: row.horizon_days,
  fill_price: fill,
  asset_last_close: assetLast,
  asset_return: pct(assetReturn),
  benchmark_return: pct(benchmarkReturn),
  alpha: pct(alpha),
  as_of: a[a.length - 1].t,
};
const lesson = 'Experiment ' + row.experiment_id + ' (' + row.asset + ' vs ' + row.benchmark + '): ' + outcome.verdict_label + '. Asset ' + outcome.asset_return + ' vs benchmark ' + outcome.benchmark_return + ' (alpha ' + outcome.alpha + ') over ' + tradingDays + ' trading days. The Bet: ' + row.falsifiable_claim;
return [{ json: { ok: true, experiment_id: row.experiment_id, asset: row.asset, outcome, lesson, record_status: row.status === 'closed' ? 'closed' : (complete ? 'evaluated' : 'approved') } }];

const body = $('ThesisLab Webhook').first().json.body || {};
const row = $input.first().json || {};
const reasons = [];
const confirmed = body.confirm === true || body.confirm === 'true';
const earlyExit = body.early_exit === true || body.early_exit === 'true';
if (!row.experiment_id) {
  reasons.push('Experiment not found');
} else {
  if (row.status === 'closed') reasons.push('Position for this experiment is already closed.');
  else if (!['approved', 'evaluated'].includes(row.status)) reasons.push('Experiment status is "' + row.status + '"; only approved experiments with a paper position can be closed.');
  if (!row.order_id) reasons.push('No entry paper order is recorded for this experiment.');
  if (row.status === 'approved' && !earlyExit) reasons.push('Horizon not confirmed complete. Run action=evaluate first (status becomes "evaluated" when the horizon ends), or send early_exit=true to deliberately close early.');
}
if (!confirmed) reasons.push('Explicit human confirmation (confirm: true) is required to close a position');
return [{ json: {
  ok: reasons.length === 0,
  reasons,
  experiment_id: row.experiment_id || body.experiment_id || null,
  asset: row.asset || null,
  benchmark: row.benchmark || null,
  order_id: row.order_id || null,
  early_exit: row.status === 'approved' && earlyExit,
  outcome: row.outcome || '',
} }];
